<template>
  <view class="withdraw-page"><jk-page-nav title="提现申请"/><view class="withdraw-content"><view class="available-card"><view><text>可用金额（元）</text><strong>{{money(account.availableAmount)}}</strong><small>总余额 {{money(totalBalance)}} 元 ›</small></view><image src="/static/jk-ui-v2/illustrations/finance-hero.png" mode="aspectFit"/></view><view class="card amount-card"><view class="section-head"><text>提现金额（元）</text><text @tap="fillAll">全部提现</text></view><view class="amount-input"><text>¥</text><input v-model="amount" type="digit" placeholder="请输入提现金额"/></view><small>最低提现金额为 {{money(config.minAmount||config.minWithdrawAmount||1)}} 元，提现金额需为 {{money(config.stepAmount||1)}} 的整数倍</small></view><view class="card account-card"><view class="section-head"><text>到账账户</text><text @tap="showAccountMissing">更换账户 ›</text></view><view class="bank-row"><jk-icon name="wallet" size="lg"/><view><text>{{payeeName}}</text><small>{{payeeAccount}}</small></view><text>›</text></view></view><view class="card remark-card"><view class="section-head"><text>备注 <small>（选填）</small></text></view><textarea v-model="remark" maxlength="50" placeholder="请输入备注信息（选填）"/><text>{{remark.length}}/50</text></view><view class="tip-card"><jk-icon name="clock" size="sm"/><view><text>温馨提示</text><small>提现申请提交后，预计 {{arrivalText}} 内到账；</small><small>工作日 9:00–17:00 提现，通常当天处理更快。</small></view></view><button class="primary-btn" :disabled="submitting||!validAmount" @tap="submit">{{submitting?'提交中...':'提交申请'}}</button><view class="agreement" @tap="agreed=!agreed"><view :class="{checked:agreed}">{{agreed?'✓':''}}</view><text>我已阅读并同意《提现服务协议》</text></view></view></view>
</template>
<script>
import JkPageNav from'@/components/jk/jk-page-nav.vue';import JkIcon from'@/components/jk/jk-icon.vue';import{getJkFundAccount,getJkWithdrawConfig,applyJkWithdraw}from'@/api/jk.js';
export default{components:{JkPageNav,JkIcon},data(){return{account:{},config:{},amount:'',remark:'',agreed:true,submitting:false}},computed:{totalBalance(){return this.account.totalAmount||Number(this.account.availableAmount||0)+Number(this.account.frozenAmount||0)+Number(this.account.withdrawingAmount||0)},validAmount(){const n=Number(this.amount);return this.agreed&&n>0&&n<=Number(this.account.availableAmount||0)&&n>=Number(this.config.minAmount||this.config.minWithdrawAmount||1)},payeeName(){return this.config.bankName||this.config.payeeBankName||'提现到账银行卡'},payeeAccount(){return this.config.bankAccountMask||this.config.payeeAccountMask||'请在后台配置收款账户'},arrivalText(){return this.config.arrivalTimeText||'1–2 个工作日'}},onShow(){this.load()},methods:{load(){getJkFundAccount().then(r=>this.account=r.data||r||{}).catch(()=>{});getJkWithdrawConfig().then(r=>this.config=r.data||r||{}).catch(()=>{})},money(v){const n=Number(v||0);return Number.isNaN(n)?String(v||'0.00'):n.toFixed(2)},fillAll(){this.amount=this.money(this.account.availableAmount)},showAccountMissing(){uni.showToast({title:'当前后端未提供收款账户切换接口',icon:'none'})},submit(){if(!this.agreed)return this.$util.Tips({title:'请先同意提现服务协议'});if(!this.validAmount)return this.$util.Tips({title:'请输入有效提现金额'});this.submitting=true;applyJkWithdraw({amount:String(this.amount),requestNo:'WD'+Date.now(),remark:this.remark,payeeSnapshotJson:JSON.stringify({bankName:this.payeeName,account:this.payeeAccount})}).then(()=>{uni.showToast({title:'申请已提交'});setTimeout(()=>uni.redirectTo({url:'/pages/jk/withdraw/list'}),500)}).catch(e=>this.$util.Tips({title:e||'提现申请提交失败'})).finally(()=>this.submitting=false)}}};
</script>
<style scoped>
.withdraw-page{min-height:100vh;background:#f7f9f9}.withdraw-content{padding:14rpx 22rpx 38rpx}.available-card{position:relative;display:flex;align-items:center;min-height:170rpx;overflow:hidden;padding:24rpx;border-radius:20rpx;background:linear-gradient(135deg,#e8faf6,#f8fffd)}.available-card>view{position:relative;z-index:2}.available-card text{display:block;color:#718087;font-size:21rpx}.available-card strong{display:block;margin-top:8rpx;color:#10b981;font-size:42rpx}.available-card small{display:block;margin-top:8rpx;color:#56aa92;font-size:19rpx}.available-card image{position:absolute;right:-18rpx;width:210rpx;height:210rpx;opacity:.5}.card{margin-top:16rpx;padding:22rpx;border-radius:19rpx;background:#fff}.section-head{display:flex;align-items:center;justify-content:space-between}.section-head>text:first-child{color:#1f2937;font-size:26rpx;font-weight:700}.section-head>text:last-child{color:#10b981;font-size:20rpx}.section-head small{color:#9aa3a8;font-size:18rpx;font-weight:400}.amount-input{display:flex;align-items:center;height:92rpx;border-bottom:1rpx solid #edf1f0}.amount-input>text{color:#263139;font-size:38rpx}.amount-input input{flex:1;height:80rpx;margin-left:8rpx;font-size:35rpx}.amount-card>small{display:block;margin-top:12rpx;color:#8b969c;font-size:18rpx}.bank-row{display:flex;align-items:center;margin-top:16rpx}.bank-row>view:nth-child(2){display:flex;flex:1;flex-direction:column;gap:6rpx;margin-left:10rpx}.bank-row text{color:#273239;font-size:22rpx}.bank-row small{color:#8b969c;font-size:18rpx}.bank-row>text:last-child{color:#9aa4aa;font-size:32rpx}.remark-card{position:relative}.remark-card textarea{width:100%;height:120rpx;margin-top:12rpx;padding:15rpx;border-radius:12rpx;background:#f8faf9;font-size:22rpx;box-sizing:border-box}.remark-card>text{position:absolute;right:34rpx;bottom:32rpx;color:#9fa8ac;font-size:17rpx}.tip-card{display:flex;align-items:flex-start;gap:10rpx;margin-top:16rpx;padding:18rpx;border-radius:15rpx;background:#f3f8f6}.tip-card>view{display:flex;flex:1;flex-direction:column;gap:5rpx}.tip-card text{color:#496159;font-size:21rpx}.tip-card small{color:#7d8d87;font-size:18rpx}.primary-btn{height:80rpx;margin-top:18rpx;border-radius:40rpx;background:#10b981;color:#fff;font-size:27rpx;line-height:80rpx}.primary-btn[disabled]{opacity:.5}.agreement{display:flex;align-items:center;justify-content:center;gap:8rpx;margin-top:14rpx;color:#7b888e;font-size:18rpx}.agreement>view{display:flex;align-items:center;justify-content:center;width:24rpx;height:24rpx;border:2rpx solid #bec8c6;border-radius:50%;font-size:16rpx}.agreement>view.checked{border-color:#10b981;background:#10b981;color:#fff}.agreement text{color:#10a981}
</style>
